"""Build the Fixbook blog. Python standard library only."""
import html, json, pathlib, re, shutil
from urllib.parse import quote

ROOT = pathlib.Path(__file__).parent
OUT = ROOT / 'site'
CONFIG = json.loads((ROOT / 'config.json').read_text(encoding='utf-8'))
BASE = CONFIG['url'].rstrip('/')

def esc(value): return html.escape(str(value), quote=True)
def code(value):
    return '<div class="code"><button class="copy" type="button">Copy</button><pre><code>' + esc(value) + '</code></pre></div>'

REG = r'HKCU\Software\Policies\Microsoft\Edge\WebView2\AdditionalBrowserArguments'
query = f'reg query "{REG}" /v WhatsApp.Root.exe'
add = f'reg add "{REG}" /v WhatsApp.Root.exe /t REG_SZ /d "--lang=tr-TR" /f'
undo = f'reg delete "{REG}" /v WhatsApp.Root.exe /f'
process = "Get-CimInstance Win32_Process |\nWhere-Object { $_.Name -eq 'msedgewebview2.exe' -and $_.CommandLine -match 'WhatsApp' } |\nSelect-Object -ExpandProperty CommandLine"
languages = '''<div class="table-wrap"><table><thead><tr><th>Language</th><th>Locale example</th><th>Test status</th></tr></thead><tbody><tr><td>Turkish</td><td><code>tr-TR</code></td><td>Confirmed in this case</td></tr><tr><td>German</td><td><code>de-DE</code></td><td>Not tested here</td></tr><tr><td>French</td><td><code>fr-FR</code></td><td>Not tested here</td></tr><tr><td>Spanish</td><td><code>es-ES</code></td><td>Not tested here</td></tr><tr><td>British English</td><td><code>en-GB</code></td><td>Not tested here</td></tr></tbody></table></div>'''

POSTS = [dict(slug='whatsapp-desktop-wrong-spellcheck-language', number='001', app='WhatsApp', category='Windows', minutes=6,
    title='WhatsApp underlines correct words? Fix the spell-check language.',
    description='A tested WebView2 workaround for WhatsApp Desktop when the spell checker ignores your writing language. Keep Windows in English.',
    body='''<p class="lead">Your keyboard is set correctly. The language pack is installed. Yet WhatsApp underlines almost every word in your language and suggests English replacements.</p>
<div class="callout"><strong>The fix that worked</strong><p>Start WhatsApp’s WebView2 component with the desired language using an app-specific registry override. In our test, <code>--lang=tr-TR</code> enabled Turkish spell checking while Windows stayed in English.</p></div>
<h2 id="scope">Tested environment</h2><ul><li>Windows 11, English display language.</li><li>WhatsApp Desktop <code>2.3000.1053651158.264201</code>.</li><li>Microsoft Edge WebView2 <code>157.0.4341.42</code>.</li><li>Writing language: Turkish. Confirmed on 8 November 2026.</li></ul>
<p>This is a local workaround, not an official WhatsApp setting. Microsoft documents WebView2 flags as diagnostic/development options that may change or disappear. Other languages and versions need their own verification.</p>
<h2 id="symptom">How to recognize this problem</h2><p>Correct words such as <em>merhaba</em> and <em>selam</em> receive red underlines, while the context menu suggests English words. Changing the keyboard, Windows language order or the app’s interface language did not fix this case.</p>
<h2 id="fix">Apply the workaround</h2><h3>1. Check for an existing override</h3><p>Open PowerShell under the Windows account that runs WhatsApp. Run:</p>''' + code(query) + '''<p>If Windows says the registry key or value cannot be found, continue. If it returns an existing value, save its exact contents before making changes. Do not replace existing arguments blindly; they may serve another purpose.</p>
<h3>2. Set the writing language</h3><p>For the tested Turkish case, run:</p>''' + code(add) + '''<p>This creates one current-user value named <code>WhatsApp.Root.exe</code>. It does not change Windows’ display language. Use the language table below to understand other locale codes; those variants have not been confirmed in this case.</p>
<h3>3. Fully close and reopen WhatsApp</h3><p>Use <strong>Task Manager → Processes → WhatsApp → End task</strong>, then launch WhatsApp again. Closing its window may only minimize it to the system tray.</p>
<h3>4. Check the result</h3><p>With <strong>Settings → Chats → Spell check</strong> enabled, type correct words in your language followed by an intentionally invented word. Correct Turkish words stopped being underlined in our test, while the invented word remained marked.</p>
<h2 id="languages">Use a different language</h2><p>The method is written around a language code, not around Turkish text. Replace <code>tr-TR</code> with the desired locale to test another language. A locale code alone does not guarantee that its dictionary is installed or supported.</p>''' + languages + '''
<h2 id="diagnostics">Check the startup language</h2><p>If the workaround does not take effect, inspect WhatsApp’s WebView2 processes:</p>''' + code(process) + '''<p>Look for processes belonging to <code>WhatsApp.Root.exe</code> and the <code>WhatsAppDesktop</code> data folder. In the original case, renderer and utility processes had <code>--lang=en-US</code>. This is a useful clue about runtime language, not proof by itself of the dictionary being used.</p>
<h2 id="undo">Undo the change</h2><p>If there was no previous value, remove only the value created above:</p>''' + code(undo) + '''<p>Fully close and reopen WhatsApp. If a value already existed before the test, restore its original contents instead of deleting it.</p>
<h2 id="did-not-work">What did not work in this case</h2><ul><li>Reordering Windows’ preferred languages and restarting Windows.</li><li>Changing the keyboard or enabling multilingual text suggestions.</li><li>Changing WhatsApp’s interface language to Turkish.</li><li>Editing <code>spellcheck</code> and <code>intl.selected_languages</code> in the WebView2 Preferences file: WhatsApp rewrote the settings on startup.</li></ul>
<h2 id="sources">References</h2><ul><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/webview2/reference/win32/webview2-idl">Microsoft: application-specific WebView2 registry overrides</a></li><li><a href="https://learn.microsoft.com/en-us/microsoft-edge/webview2/concepts/webview-features-flags">Microsoft: WebView2 flags, including lang, and their limitations</a></li></ul>'''),
dict(slug='chatgpt-codex-wrong-spellcheck-language', number='002', app='ChatGPT / Codex', category='Windows', minutes=5,
    title='Change the spell-check dictionary in ChatGPT / Codex Desktop.',
    description='Add your writing language to the desktop app’s Preferences file when correct words are flagged as English spelling errors.',
    body='''<p class="lead">If correct words in your language are underlined in ChatGPT / Codex Desktop, the app’s own dictionary list may contain only English—even when Windows has the right language installed.</p>
<div class="callout"><strong>The fix that worked</strong><p>Back up the active <code>Preferences</code> file, fully quit the app, and add your writing language to its <code>spellcheck</code> section.</p></div>
<h2 id="scope">Tested case</h2><p>Windows 11 with an English display language, using the combined ChatGPT / Codex desktop app. Turkish spell checking was confirmed on 8 November 2026. The exact app version was not recorded. This workaround may differ across app versions and installation types.</p>
<h2 id="locate">1. Find the active profile</h2><p>Press <strong>Win + R</strong> and open:</p>''' + code(r'%LOCALAPPDATA%\Packages') + '''<p>For the tested Microsoft Store installation, the file was under:</p>''' + code(r'OpenAI.Codex_2p2nqsd0c76g0\LocalCache\Roaming\Codex\web\Codex\Default\Preferences') + '''<p>Some installations use the following location instead. Verify that it actually exists; paths vary.</p>''' + code(r'%APPDATA%\Codex\web\Codex\Default\Preferences') + '''<p>Use the file named <strong>Preferences</strong>, not <strong>Secure Preferences</strong>. Do not edit login databases or delete the profile folder.</p>
<h2 id="fix">2. Back up, quit and edit</h2><p>Copy <code>Preferences</code> to <code>Preferences.backup</code>. Fully quit the app, including any background process, before editing. Open the original file in a text editor and find <code>spellcheck</code>.</p><p>The original section in this case was:</p>''' + code('"spellcheck":{"dictionaries":["en-US"],"dictionary":""}') + '''<p>Replace that section—not the entire file—with:</p>''' + code('"spellcheck":{"dictionaries":["tr-TR","tr","en-US"],"dictionary":"tr-TR"}') + '''<p>Keep the surrounding JSON commas and braces intact. Save to the original <code>Preferences</code> filename without adding a <code>.txt</code> extension.</p>
<h2 id="verify">3. Reopen and verify</h2><p>Launch the app and type correct words followed by an invented word. In our test, correct Turkish words no longer received red underlines, but the invented word still did. Windows remained in English.</p>
<h2 id="languages">Other languages</h2><p>Use your language’s supported dictionary code rather than assuming Turkish codes apply. The table gives locale examples; only Turkish was tested here. Regional and base-language codes may behave differently.</p>''' + languages + '''
<h2 id="undo">Undo the edit</h2><p>Fully quit the app. Preserve a copy of the current file, then restore <code>Preferences.backup</code> as <code>Preferences</code>. The backup restores all preferences as they were at backup time, so later preference changes may be lost.</p>
<h2 id="limits">If the file changes back</h2><p>First verify the app was fully stopped. If it still rewrites your dictionary list, stop repeating the same edit. Another profile or an app-controlled startup setting may be involved. Updates may also reset the workaround. Do not make the entire file read-only.</p>
<p>WhatsApp behaved differently in our session: its Preferences edits did not persist. Use the <a href="whatsapp-desktop-wrong-spellcheck-language.html">separate WhatsApp workaround</a> for that tested case.</p>
<h2 id="sources">References</h2><ul><li><a href="https://github.com/openai/codex/issues/25431">OpenAI Codex issue #25431: spell-check settings and community workarounds</a></li><li><a href="https://community.openai.com/t/windows-app-disable-spell-check/1062913">OpenAI community: desktop spell-check preferences</a></li></ul>''')]

def shell(title, desc, content, path='index.html', article=None):
    canonical = BASE + '/' + ('' if path == 'index.html' else path)
    data = {'@context':'https://schema.org','@type':'BlogPosting' if article else ('Blog' if path == 'index.html' else 'WebPage'),'name':title,'description':desc,'url':canonical,'inLanguage':'en'}
    if article:
        data.update(headline=title, datePublished='2026-11-08T12:00:00+03:00', dateModified='2026-11-08T12:00:00+03:00', author={'@type':'Person','name':'Salih','url':BASE+'/about.html'},mainEntityOfPage={'@type':'WebPage','@id':canonical},isPartOf={'@type':'Blog','name':'Sumlif Fixbook','url':BASE+'/'})
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | Sumlif Fixbook</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:url" content="{canonical}"><meta name="theme-color" content="#14392f"><link rel="icon" href="assets/icon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><link rel="alternate" type="application/rss+xml" title="Sumlif Fixbook" href="feed.xml"><script type="application/ld+json">{json.dumps(data)}</script><script defer src="assets/app.js"></script></head><body><a class="skip" href="#main">Skip to content</a><header class="header"><a class="brand" href="index.html"><span class="brand-icon">F<span>↗</span></span><span>sumlif<span class="brand-light"> / fixbook</span></span></a><nav aria-label="Main"><a href="index.html#notes">The fixes</a><a href="about.html">About</a><a class="github" href="https://github.com/{CONFIG['repo']}">GitHub ↗</a></nav></header>{content}<footer><a class="brand" href="index.html">Sumlif Fixbook<span class="dot">.</span></a><p>A growing notebook of problems actually solved.</p><div><a href="feed.xml">RSS feed</a><a href="privacy.html">Privacy</a><a href="https://github.com/{CONFIG['repo']}">Source ↗</a></div><small>By Salih · Built to be useful.</small></footer></body></html>'''

def write(path, text):
    if path.endswith('.html'):
        style = (ROOT / 'assets' / 'style.css').read_text(encoding='utf-8')
        script = (ROOT / 'assets' / 'app.js').read_text(encoding='utf-8')
        runtime = json.dumps({'repo': CONFIG['repo'], 'comments': CONFIG['comments'], 'analytics_endpoint': CONFIG['analytics_endpoint']})
        text = text.replace('<link rel="stylesheet" href="assets/style.css">', '<style>' + style + '</style>')
        text = text.replace('<script defer src="assets/app.js"></script>', '')
        text = text.replace('<meta name="theme-color"', '<meta name="robots" content="' + ('noindex,follow' if path == '404.html' else 'index,follow,max-image-preview:large') + '"><meta property="og:site_name" content="Sumlif Fixbook"><meta name="twitter:card" content="summary"><meta name="theme-color"')
        text = text.replace('</body>', '<script type="application/json" id="fixbook-config">' + runtime + '</script><script>' + script + '</script></body>')
    dest = OUT / path; dest.parent.mkdir(parents=True, exist_ok=True); dest.write_text(text, encoding='utf-8')

OUT.mkdir(exist_ok=True)
cards = ''
for p in POSTS:
    cards += f'''<a class="card" data-search="{esc(p['title']+' '+p['description']+' '+p['app'])}" data-app="{esc(p['app'])}" href="{p['slug']}.html"><div class="card-top"><span class="tag">{esc(p['app'])}</span><span class="note-number">NOTE / {p['number']}</span></div><h3>{esc(p['title'])}</h3><p>{esc(p['description'])}</p><div class="card-bottom"><span>08 Nov 2026 · {p['minutes']} min read</span><span class="arrow">↗</span></div></a>'''
home = '''<main id="main"><section class="hero"><div><p class="eyebrow"><span class="dot-indicator"></span> AN ENGINEER’S OPEN NOTEBOOK</p><h1>Real problems.<br>Working <em>fixes.</em></h1><p class="hero-description">The steps that finally worked, the attempts that didn’t, and a way back. Practical troubleshooting notes, one solved problem at a time.</p><a class="button" href="#notes">Explore the fixes <span>↓</span></a><div class="hero-meta"><span>Written by Salih</span><span>Free to read. Made to share.</span></div></div><aside class="hero-note"><div class="note-head"><span>FROM THE WORKBENCH</span><span>01 — 02</span></div><div class="note-icon">✓</div><h2>Keep the fix.<br>Skip the guesswork.</h2><p>Clear symptoms.<br>Steps you can reproduce.<br>Tested scope. Undo instructions.</p><div class="note-foot"><span class="dot-indicator"></span> Two fixes. One notebook. More to come.</div></aside></section><section class="notes" id="notes"><div class="section-title"><div><p class="eyebrow">THE NOTEBOOK</p><h2>Latest field notes<span class="dot">.</span></h2></div><p>Small discoveries worth keeping.</p></div><div class="tools"><div class="filters" role="group" aria-label="Filter by application"><button class="filter active" data-filter="all" aria-pressed="true">All notes <span>2</span></button><button class="filter" data-filter="WhatsApp" aria-pressed="false">WhatsApp</button><button class="filter" data-filter="ChatGPT / Codex" aria-pressed="false">ChatGPT / Codex</button></div><label class="search"><span aria-hidden="true">⌕</span><input type="search" id="search" placeholder="Search the notebook…" aria-label="Search articles"></label></div><p class="sr-only" id="result-status" aria-live="polite"></p><div class="cards">''' + cards + '''</div><p id="empty" hidden>No matching notes yet. Try another word or application.</p></section><section class="principles"><div><span>01 / OBSERVE</span><h3>Start with the symptom.</h3><p>Recognize the problem before changing a setting.</p></div><div><span>02 / REPRODUCE</span><h3>Show the actual fix.</h3><p>Commands, context and the version that was tested.</p></div><div><span>03 / SHARE</span><h3>Leave a useful trail.</h3><p>Ask a question. Report what worked on your setup.</p></div></section></main>'''
write('index.html', shell('Real problems. Working fixes.', 'An engineer’s troubleshooting blog. Practical Windows and software fixes with tested steps, language examples and undo instructions.', home))
for p in POSTS:
    heads = re.findall(r'<h2 id="([^"]+)">([^<]+)</h2>', p['body'])
    toc = ''.join(f'<a href="#{a}">{esc(b)}</a>' for a,b in heads)
    question_url = 'https://github.com/' + CONFIG['repo'] + '/issues/new?title=' + quote('Question: '+p['title']) + '&body=' + quote('Article: '+BASE+'/'+p['slug']+'.html\n\nApp version:\nWindows version:\nWriting language:\n\nWhat happened?\n\nPlease remove personal data from logs and screenshots.')
    comments = f'''<section class="discussion" id="discussion"><p class="eyebrow">COMPARE NOTES</p><h2>Questions &amp; discussion</h2><p>Did this work on your version or in another language? Share your setup or ask a question. A GitHub account is required to post. Comments are public; remove personal details from logs.</p><a class="button secondary" href="{esc(question_url)}">Ask a question on GitHub ↗</a><div id="comments"></div></section>'''
    page = f'''<main id="main"><section class="article-heading"><a class="back" href="index.html#notes">← Back to the notebook</a><div class="article-label"><span class="tag">{esc(p['app'])}</span><span class="note-number">NOTE / {p['number']}</span></div><h1>{esc(p['title'])}</h1><div class="byline">Salih <span>·</span> 08 November 2026 <span>·</span> {p['minutes']} min read</div><p class="tested">✓ Confirmed in one real troubleshooting session · Turkish tested</p></section><div class="article-layout"><aside class="toc"><p>ON THIS PAGE</p>{toc}<a href="#discussion">Questions &amp; discussion</a></aside><article>{p['body']}{comments}</article></div><section class="next"><p class="eyebrow">KEEP EXPLORING</p><a href="{POSTS[1 if p == POSTS[0] else 0]['slug']}.html">{esc(POSTS[1 if p == POSTS[0] else 0]['title'])} →</a></section></main>'''
    write(p['slug']+'.html', shell(p['title'],p['description'],page,p['slug']+'.html',p))
write('about.html', shell('About the notebook', 'Why Sumlif Fixbook exists and how its troubleshooting notes are verified.', '''<main id="main" class="simple"><p class="eyebrow">ABOUT FIXBOOK</p><h1>Useful things<br>we learned the hard way.</h1><p class="lead">I’m Salih, an engineer. Fixbook is a place to keep practical solutions from real troubleshooting sessions so the next person can get there faster.</p><h2>One notebook, growing over time</h2><p>New problems become new posts here. Every note describes a specific symptom, the steps that worked, and how to undo the change.</p><h2>What “tested” means</h2><p>A fix worked in the setup described in the article. It does not mean every device, version or language has been tested. Untested language examples are labeled clearly.</p><h2>Help improve a note</h2><p>Use the question link beneath an article to report a different result, ask for clarification or contribute another language test. Please include versions and avoid posting personal information.</p></main>''','about.html'))
write('privacy.html', shell('Privacy', 'How comments and optional analytics work on Sumlif Fixbook.', '''<main id="main" class="simple"><p class="eyebrow">PRIVACY</p><h1>A small site.<br>A clear data trail.</h1><h2>Hosting</h2><p>This site is designed for GitHub Pages. GitHub may process connection information when serving pages. See <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub’s privacy statement</a>.</p><h2>Questions and comments</h2><p>Question links open GitHub Issues. Posts and account names are public. If embedded comments are enabled, they load through Utterances and GitHub; signing in is required only to post. Do not publish credentials, private messages or personal paths.</p><h2>Optional traffic measurement</h2><p>The blog includes an optional GoatCounter integration for per-page views and aggregate visitor/referrer trends. No analytics script loads until the site owner configures a valid endpoint. Browser blockers can prevent measurements; counts are not an exact record of every visitor. See <a href="https://www.goatcounter.com/privacy">GoatCounter’s privacy information</a>.</p><h2>On this site</h2><p>No advertising, newsletter signup or visitor account system is included. Search and category filtering run in your browser.</p></main>''','privacy.html'))
write('404.html', shell('Page not found', 'Find a troubleshooting note in the Fixbook archive.', '<main id="main" class="simple"><p class="eyebrow">404 / NOTE NOT FOUND</p><h1>That page took<br>a wrong turn.</h1><p><a href="'+BASE+'/index.html">Return to the notebook →</a></p></main>','404.html'))
for name in ['style.css','app.js','icon.svg']:
    dest = OUT / 'assets' / name; dest.parent.mkdir(exist_ok=True); shutil.copyfile(ROOT/'assets'/name,dest)
write('assets/config.json',json.dumps({'repo':CONFIG['repo'],'comments':CONFIG['comments'],'analytics_endpoint':CONFIG['analytics_endpoint']}))
write('.nojekyll','')
write('robots.txt',f'User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n')
paths = ['index.html','about.html','privacy.html']+[p['slug']+'.html' for p in POSTS]
write('sitemap.xml','<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}/{"" if p == "index.html" else p}</loc><lastmod>2026-11-08</lastmod></url>' for p in paths)+'</urlset>')
write('feed.xml','<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>Sumlif Fixbook</title><link>'+BASE+'/</link><description>Real problems. Working fixes.</description>'+''.join(f'<item><title>{esc(p["title"])}</title><link>{BASE}/{p["slug"]}.html</link><guid>{BASE}/{p["slug"]}.html</guid><description>{esc(p["description"])}</description><pubDate>Sun, 08 Nov 2026 12:00:00 +0000</pubDate></item>' for p in POSTS)+'</channel></rss>')
print(f'Built {len(paths)+4} pages/feeds in {OUT}')
